class anim_vector
{
public:
    entity_anim_tree **start;
    entity_anim_tree **finish;
    entity_anim_tree **end_of_storage;

    void resize(unsigned int n)
    {
        entity_anim_tree *value = 0;
        unsigned int current = finish - start;
        if (n < current) {
            unsigned int removed = current - n;
            __builtin_memmove(start + n, finish, 0);
            finish -= removed;
        } else if (n > current) {
            vector_insert(this, finish, n - current, value);
        }
    }

    ~anim_vector()
    {
        unsigned int count = end_of_storage - start;
        if (count)
            my_alloc::deallocate(start, count * sizeof(entity_anim_tree *));
    }
};

